<?php
declare(strict_types=1);

/**
 * SMA-Move — Create Care Task Endpoint
 *
 * POST /api/careplan/create_task.php
 *
 * Clinician- or patient-defined care tasks with step-by-step guidance.
 * Not automatically generated by AI.
 */

require_once dirname(dirname(__DIR__)) . '/config/config.php';
require_once dirname(dirname(__DIR__)) . '/middleware/cors.php';
require_once dirname(dirname(__DIR__)) . '/middleware/auth_middleware.php';
require_once dirname(dirname(__DIR__)) . '/middleware/request_validation.php';
require_once dirname(dirname(__DIR__)) . '/models/CareTask.php';
require_once dirname(dirname(__DIR__)) . '/models/ProfessionalProfile.php';
require_once dirname(dirname(__DIR__)) . '/models/PatientProfessionalAccess.php';
require_once dirname(dirname(__DIR__)) . '/utils/response.php';

use SmaMove\Middleware\CorsMiddleware;
use SmaMove\Middleware\AuthMiddleware;
use SmaMove\Middleware\RequestValidator;
use SmaMove\Models\CareTask;
use SmaMove\Models\ProfessionalProfile;
use SmaMove\Models\PatientProfessionalAccess;
use SmaMove\Utils\Response;

CorsMiddleware::handle();

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    Response::methodNotAllowed('Only POST requests are allowed.');
}

$user = AuthMiddleware::authenticate();

$input = RequestValidator::validate([
    'title' => ['required', 'string', 'max:200'],
    'description' => ['required', 'string'],
    'category' => ['required', 'enum:Respiratory care,Positioning,Hydration,Care coordination,Wellbeing,Mobility']
]);

$patientUserId = (int)$user['id'];

if ($user['role'] === 'professional') {
    $requestedPatientId = isset($input['patient_id']) ? (int)$input['patient_id'] : 0;
    if ($requestedPatientId <= 0) {
        Response::badRequest('patient_id is required when creating a task as a healthcare professional.');
    }

    if (!ProfessionalProfile::isVerified($user['id'])) {
        Response::forbidden('Access denied. Professional profile is not verified.');
    }

    if (!PatientProfessionalAccess::isAuthorized($user['id'], $requestedPatientId)) {
        Response::forbidden('Access denied. You have not been authorized by this patient.');
    }

    $patientUserId = $requestedPatientId;
    $input['prescribed_by'] = $input['prescribed_by'] ?? ($user['full_name'] . ' (Clinical Prescription)');
} elseif ($user['role'] !== 'patient') {
    Response::forbidden('Only patients and authorized healthcare professionals can define care plan tasks.');
}

$steps = isset($input['steps']) && is_array($input['steps']) ? $input['steps'] : [];

try {
    $taskId = CareTask::createTask($patientUserId, $input, $steps);
    $createdTask = CareTask::findById($taskId, $patientUserId, date('Y-m-d'));

    Response::created([
        'task' => $createdTask
    ], 'Care task created successfully.');
} catch (\Throwable $e) {
    error_log("[Create Care Task Error] " . $e->getMessage());
    Response::serverError('Unable to create care task.');
}
